import sympy

def build_instance(rng):
    h = rng.randint(-5, 5)
    shift = rng.randint(1, 5)
    target_value = rng.randint(1, 25)
    x = sympy.symbols('x', real=True)
    f = (x - h) ** 2 + shift
    equation = sympy.Eq(f, target_value)
    solutions = sympy.solve(equation, x)
    answer = len(solutions)
    check = sum((1 for sol in solutions if sol.is_real))
    parameters = {'h': h, 'shift': shift, 'target_value': target_value}
    return (parameters, answer, check)



