import fractions
import sympy

def build_instance(rng):
    quadratic_coefficient = rng.randint(1, 8)
    linear_coefficient = rng.randint(-5, 9)
    constant_term = rng.randint(-5, 9)
    x_value = rng.randint(1, 6)
    direct_value = fractions.Fraction(quadratic_coefficient * x_value ** 2 + linear_coefficient * x_value + constant_term)
    answer = str(direct_value)
    x = sympy.symbols('x')
    polynomial = quadratic_coefficient * x ** 2 + linear_coefficient * x + constant_term
    symbolic_value = polynomial.subs(x, x_value)
    check_fraction = fractions.Fraction(int(symbolic_value))
    check = str(check_fraction)
    parameters = {'quadratic_coefficient': quadratic_coefficient, 'linear_coefficient': linear_coefficient, 'constant_term': constant_term, 'x_value': x_value}
    return (parameters, answer, check)



