def build_instance(rng):
    h = rng.randint(-5, 5)
    shift = rng.randint(1, 5)
    slope = rng.randint(-5, 5)
    y_intercept = rng.randint(-5, 5)
    answer = 'Yes' if slope == 2 * h and y_intercept == h ** 2 + shift else 'No'
    x = sympy.symbols('x', real=True)
    f = (x - h) ** 2 + shift
    line = slope * x + y_intercept
    intersection = sympy.solve(f - line, x)
    check = 'Yes' if len(intersection) == 1 else 'No'
    assert answer == check, f'answer={answer} check={check}'
    parameters = {'h': h, 'shift': shift, 'slope': slope, 'y_intercept': y_intercept}
    return (parameters, answer, check)



